  // Round-robin circle method: each club has one reciprocal fixture per week.
  const rounds = [];
  let rotation = clubs.map((c) => c.id);
  for (let week = 0; week < 4; week++) {
    const games = [];
    for (let i = 0; i < rotation.length / 2; i++) {
      const pair = [rotation[i], rotation[rotation.length - 1 - i]];
      if ((i + week) % 2) pair.reverse();
      games.push({ home: pair[0], away: pair[1] });
    }
    rounds.push(games);
    rotation = [rotation[0], rotation.at(-1), ...rotation.slice(1, -1)];
  }
